<script setup>
import {reactive,ref,watch} from 'vue'
import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app'
import QuestionConfirmation from '../../components/QuestionConfirmation.vue'
import QuestionRecovery from '../../components/QuestionRecovery.vue'
import {operatorSession,operatorToken,clearOperatorSession} from '../../services/operator-session.js'
import {exact} from '../../services/experience-publication.js'
import {createCommunityQuestionApi,SERVICE_MODES,validQuestionBody} from '../../services/community-questions.js'
import {createCommunityQuestionRecovery,pendingQuestion,createQuestionConfirmation} from '../../services/community-question-recovery.js'
import {initialDiagnosisState,createAsyncDiagnosisFlow} from '../../services/async-diagnosis.js'
import {priceLocalUtc as localUtc,priceBeijing as beijing} from '../../services/price-policies.js'
import {imageRequestKey} from '../../services/private-images.js'
const fresh=()=>({mode:'LEAVE_MESSAGE',note:'',from:'',to:''}),form=reactive(fresh()),editing=ref(0),revision=ref(0),routeValid=ref(true),preview=ref(null),confirmation=reactive({prompt:null}),state=reactive(initialDiagnosisState()),api=createCommunityQuestionApi(),allowed=()=>routeValid.value&&operatorSession.canCommunityManage,blocked=()=>state.busy||state.retry||state.kind==='storage'
const recovery=createCommunityQuestionRecovery({actor:()=>operatorSession.actorId,role:()=> 'admin',scope:()=> 'policy'}),gate=createQuestionConfirmation({state:confirmation,preview:()=>preview.value})
const flow=createAsyncDiagnosisFlow({state,token:operatorToken,allowed,scope:()=>`question-policy:${operatorSession.actorId}`,load:api.policies,write:(t,a,n,b,k)=>api.policyWrite(t,a,n,b,k),newKey:imageRequestKey,recovery,confirm:gate.ask,onWritten:clearForm})
let visible=false
function clearForm(){Object.assign(form,fresh());editing.value=0;revision.value=0;preview.value=null}
function reset(){gate.cancel();flow.reset();clearForm()}
function login(){clearOperatorSession();uni.navigateTo({url:'/pages/operator/login'})}
function edit(p){if(blocked()||p.status!=='DRAFT'||!state.data?.items.includes(p))return;editing.value=p.id;revision.value=p.revision;Object.assign(form,{mode:p.mode,note:p.source_note,from:beijing(p.valid_from),to:beijing(p.valid_to)})}
function policyPreview(p,title){return {title,lines:[`受理模式：${SERVICE_MODES[p.mode]}`,`来源说明（仅管理可读）：${p.source_note}`,`北京时间 ${beijing(p.valid_from)} 至 ${beijing(p.valid_to)}（截止不含）`,'两种可受理模式均为非实时；来源/人员/窗口仍在新输入事务重新核验。']}}
function save(){if(blocked())return;const action=editing.value?'update':'create',b={mode:form.mode,source_note:form.note.trim(),valid_from:localUtc(form.from),valid_to:localUtc(form.to),...(editing.value?{expected_revision:revision.value}:{})};if(!validQuestionBody(b,action,true)){state.message='请填写可核对的来源、受理模式和有效起止时间。';return}preview.value=policyPreview(b,editing.value?`确认修改草稿 ${editing.value} · 版本 ${revision.value}`:'确认新建私有问答受理草稿');flow.save(action,editing.value,b)}
function status(p,to){if(blocked()||!state.data?.items.includes(p))return;preview.value=policyPreview(p,`确认${to==='PUBLISHED'?'发布冻结':'停止'}配置 ${p.id} · 当前版本 ${p.revision}`);preview.value.lines.push(to==='PUBLISHED'?'发布后内容冻结；全局最多一个发布版本。':'停止后不接受新提问或补充；已有问答仍可由获派人员处理。');flow.save('status',p.id,{expected_revision:p.revision,status:to})}
watch(()=>[operatorSession.accessToken,operatorSession.actorId,allowed()],()=>{reset();if(visible&&operatorToken()&&allowed())flow.load()},{flush:'sync'})
watch(()=>state.kind,k=>{if(['unauthorized','forbidden','missing'].includes(k)){gate.cancel();clearForm()}},{flush:'sync'})
onLoad(q=>routeValid.value=exact(q||{},[]));onShow(()=>{visible=true;if(operatorToken()&&allowed())flow.load()});function hide(){visible=false;reset()}onHide(hide);onUnload(hide)
</script>
<template><view class="reservation-page"><text class="reservation-title">私有问答受理政策</text><text>独立问答管理权限；未配置显示未知，缺有效处理人员或窗口外不接受新输入。来源说明不向车主公开。</text><text v-if="!routeValid">配置入口参数无效。</text><button v-if="!operatorToken()" @tap="login">运营登录</button><text v-else-if="!allowed()">当前账号没有问答管理权限。</text><button v-if="['unauthorized','forbidden'].includes(state.kind)" @tap="login">重新登录</button><QuestionRecovery :state="state" :flow="flow" :pending="pendingQuestion(recovery)"/><button :disabled="state.busy" @tap="flow.load(state.page)">读取当前政策</button><template v-if="allowed()"><view class="reservation-panel"><text>{{editing?'修改草稿 '+editing:'新建受理草稿'}}</text><picker :range="Object.values(SERVICE_MODES)" :disabled="blocked()" @change="form.mode=Object.keys(SERVICE_MODES)[Number($event.detail.value)]"><view>{{SERVICE_MODES[form.mode]}}</view></picker><textarea v-model="form.note" maxlength="256" :disabled="blocked()" placeholder="仅运营管理可见的受理来源说明"/><input v-model="form.from" maxlength="19" :disabled="blocked()" placeholder="北京时间生效 YYYY-MM-DD HH:mm:ss"/><input v-model="form.to" maxlength="19" :disabled="blocked()" placeholder="北京时间截止 YYYY-MM-DD HH:mm:ss"/><button :disabled="blocked()" @tap="save">预览并保存草稿</button><button :disabled="blocked()" @tap="clearForm">新建另一配置</button></view><template v-if="state.data"><text v-if="!state.data.items.length">暂无受理政策；车主端显示未知。</text><view v-for="p in state.data.items" :key="p.id" class="reservation-panel"><text>配置 {{p.id}} · {{p.status}} · 版本 {{p.revision}} · {{SERVICE_MODES[p.mode]}}</text><text>{{p.source_note}}</text><text>北京时间 {{beijing(p.valid_from)}} 至 {{beijing(p.valid_to)}}</text><button v-if="p.status==='DRAFT'" :disabled="blocked()" @tap="edit(p)">修改当前草稿</button><button v-if="p.status==='DRAFT'" :disabled="blocked()" @tap="status(p,'PUBLISHED')">预览发布冻结</button><button v-if="p.status==='PUBLISHED'" :disabled="blocked()" @tap="status(p,'STOPPED')">预览停止</button></view><button v-if="state.page>1" :disabled="blocked()" @tap="flow.load(state.page-1)">上一页政策</button><button v-if="state.page*20<state.data.total" :disabled="blocked()" @tap="flow.load(state.page+1)">下一页政策</button></template><button :disabled="state.busy" @tap="uni.navigateTo({url:'/pages/operator/questions?scope=queue'})">进入最小分配队列</button></template><QuestionConfirmation :prompt="confirmation.prompt" @answer="gate.settle"/></view></template>
